        [[nodiscard]] inline HANDSHAKE_STATUS doHandshake() noexcept
        {
            if (ssl_ == nullptr || handshakeDone_) [[likely]]
            {
                return HANDSHAKE_STATUS::DONE;
            }
            const int r = SSL_accept(ssl_);
            if (r == 1)
